mapper.select:
d.del_flag = '0'
and d.status != 'voided'
and d.status = #{status}
and d.doc_no like concat('%', #{docNo}, '%')
and d.customer_id = #{customerId}
and (d.doc_no like concat('%', #{keyword}, '%') or d.customer_name_text like concat('%', #{keyword}, '%') or d.remark like concat('%', #{keyword}, '%') or exists (select 1 from t_ctms_sales_request_item it where it.doc_id = d.id and it.product_name like concat('%', #{keyword}, '%')))
and date_format(d.doc_date, '%Y-%m-%d') >= #{beginDocDate}
and date_format(d.doc_date, '%Y-%m-%d') <= #{endDocDate}
and (${dataScopeSql})
order by d.doc_date desc, d.create_time desc
